<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Base64URL Encoder & Decoder','description'=>'Encode or decode URL-safe Base64 text instantly.','url'=>'https://smarttoolz.in/tools/base64url-tool/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Base64URL Tool</h1><p>Encode and decode URL-safe Base64 text.</p></section><section class="tool-workspace"><div class="tool-panel"><textarea id="i" rows="8" placeholder="Enter text or Base64URL..."></textarea><button id="enc" class="tool-btn">Encode</button><button id="dec" class="tool-btn">Decode</button><textarea id="o" rows="8" readonly></textarea></div></section></main><script>const b=s=>btoa(unescape(encodeURIComponent(s))).replaceAll('+','-').replaceAll('/','_').replaceAll('=','');enc.onclick=()=>o.value=b(i.value);dec.onclick=()=>{try{let s=i.value.replaceAll('-','+').replaceAll('_','/');s+='='.repeat((4-s.length%4)%4);o.value=decodeURIComponent(escape(atob(s)))}catch(e){o.value='Invalid Base64URL.'}}</script><?php smarttoolz_tool_page_end(); ?>